#include <vector>
#include <cmath>
int spreadSignal(const std::vector<double>& A, const std::vector<double>& B,
                 double beta, int w){
    int n = A.size();
    if (n < w) return 0;
    std::vector<double> s(n);
    for (int i = 0; i < n; i++) s[i] = A[i] - beta * B[i];
    double mean = 0;
    for (int i = n - w; i < n; i++) mean += s[i];
    mean /= w;
    double var = 0;
    for (int i = n - w; i < n; i++) var += (s[i] - mean) * (s[i] - mean);
    var /= w;
    double sd = std::sqrt(var);
    if (sd == 0) return 0;
    double z = (s[n - 1] - mean) / sd;
    if (z > 2) return -1;
    if (z < -2) return 1;
    return 0;
}
